#!/bin/bash
# Run the PSGLA within Split-Gibbs Sampler (SGS) over all datasets described
# in .json configuration files.
#
# author: pthouvenin (pierre-antoine.thouvenin@centralelille.fr)

# * Notes
#
# ! Parameter passed as explicit command line arguments override those from
# ! the configuration .json file
#
# ! This script can only be run once the synthetic data have been generated
# ! (see "generate_data.sh")
#
# ! BEWARE: running all the simulations below requires a large amount of space
# ! on the hard drive. All samples generated by the serial samplers
# ! are saved to disk in the form of multiple checkpoint files, from which the
# ! samplers can be restarted to obtain a longer chain)

# * Configuring the experiments and SLURM

# mode to run the experiments, either "serial", "gpu" or "distributed"
mode="distributed"
ncores=2

# path to conda environment to conda and name of conda environment to be used
conda_path=/home/pierreantoine.thouvenin/miniforge3/bin/activate
env_name=mcmc

# deactivate JIT compilation for fair comparison with C++
# export NUMBA_NUM_THREADS=1
# export NUMBA_DISABLE_JIT=1

# list of configuration files for the experiment
declare -a experiments_configs=("config_cameraman_benchmark.json")

# * SLURM options (memory, time, email, path to job log files)
mail_user=pierreantoine.thouvenin@univ-lille.fr
mem=10G  # 15
time=00:45:00
logpath=logs

# * Useful slurm commands
# https://slurm.schedmd.com/quickstart.html
# https://slurm.schedmd.com/mpi_guide.html#open_mpi
# https://hpc-doc.univ-lille.fr/docs/cluster/hardware
# sinfo
# scontrol show partition
# sacct -o jobid,jobname,reqnodes,reqcpus,reqmem,maxrss,averss,elapsed -j JOBID
# sbatch --gres=help

# * Info on partitions
# PartitionName=32c3
#    AllowGroups=ALL AllowAccounts=ALL AllowQos=default,normal
#    AllocNodes=ALL Default=YES QoS=N/A
#    DefaultTime=1-00:00:00 DisableRootJobs=NO ExclusiveUser=NO GraceTime=0 Hidden=NO
#    MaxNodes=UNLIMITED MaxTime=16-00:00:00 MinNodes=0 LLN=NO MaxCPUsPerNode=UNLIMITED
#    Nodes=minos-d06-[01-12]
#    PriorityJobFactor=1 PriorityTier=1 RootOnly=NO ReqResv=NO OverSubscribe=NO
#    OverTimeLimit=NONE PreemptMode=OFF
#    State=UP TotalCPUs=384 TotalNodes=12 SelectTypeParameters=NONE
#    JobDefaults=(null)
#    DefMemPerNode=4096 MaxMemPerNode=UNLIMITED
#    TRES=cpu=384,mem=6120000M,node=12,billing=384

# PartitionName=gpu
#    AllowGroups=ALL AllowAccounts=ALL AllowQos=default,normal
#    AllocNodes=ALL Default=NO QoS=N/A
#    DefaultTime=01:00:00 DisableRootJobs=NO ExclusiveUser=NO GraceTime=0 Hidden=NO
#    MaxNodes=UNLIMITED MaxTime=16-00:00:00 MinNodes=0 LLN=NO MaxCPUsPerNode=UNLIMITED
#    Nodes=ampere-d06-01,ares-c02-01,golgoth-d06-01,turing-07-02
#    PriorityJobFactor=1 PriorityTier=1 RootOnly=NO ReqResv=NO OverSubscribe=NO
#    OverTimeLimit=NONE PreemptMode=OFF
#    State=UP TotalCPUs=248 TotalNodes=4 SelectTypeParameters=NONE
#    JobDefaults=(null)
#    DefMemPerNode=4096 MaxMemPerNode=UNLIMITED
#    TRES=cpu=248,mem=5079232M,node=4,billing=248,gres/gpu=14

# * Running experiments
# # FIXME: could specify partition required depending on run mode
# --partition=...

case $mode in

    # single cpu
    "serial")
        command=python
        partition="--partition=32c3"
        gres=""
        echo $command
        ;;

    # single gpu (on ULille grid)
    "gpu")
        command=python
        partition="--partition=gpu"
        # gres="--gres=gpu:RTX2080:1"
        gres="--gres=gpu:A100-80G:1"
        echo $command
        ;;

    # multiple cpus
    "distributed")
        command="mpiexec -n ${ncores} python -m mpi4py"
        partition="--partition=32c3"
        gres=""
        echo $command
        ;;

    *)
        echo "Unknown mode selected, default "serial"  mode considered"
        command=python
        partition="--partition=32c3"
        gres=""
        mode="serial"
        ;;
esac


mkdir $logpath

# loop over configuration files
for config in "${experiments_configs[@]}"; do

    configfile="${config}"
    echo Experiment: mode=${mode}, config=${configfile}, ncores=${ncores};

    echo "
    sbatch --job-name=dsgs.mode=${mode}.n=$ncores.$configfile \
        ${partition} \
        ${gres} \
        --mail-user=${mail_user} \
        --mem=${mem} \
        --time=${time} \
        --nodes=1 \
        --ntasks-per-node=${ncores} \
        --output=$logpath/dsgs_mode=${mode}_n=${ncores}_${config}.out \
        --error=$logpath/dsgs_mode=${mode}_n=${ncores}_${config}.err \
        --export=ncores=${ncores},conda_path=${conda_path},env_name=${env_name},command="${command}",configfile=${configfile},mode=${mode} job.slurm
    "
done
